import type { PracticeQuestion } from '../parent-practice-bank'

type QuestionRevision = Partial<PracticeQuestion>

function withText(text: string, task: string) {
  return `${text}\n\n${task}`
}

function sourceRef(group: string, task: string) {
  return `牧哲学堂原创拓展题/河北中考题型参考2026/英语/${group}#${task}`
}

function unitSourceRef(unit: number, title: string, section: number, task: string) {
  return `人教版（2024）九年级下册/Unit ${unit} ${title}/Section ${section}；牧哲学堂原创短语篇与设问，不是教材原文或中考真题#${task}`
}

type UnitChoice = { section: number; point: 1 | 2; task: string; prompt: string; options: string[]; answer: number; explanation: string }
const g9UnitQ4Templates: { unit: number; title: string; questions: UnitChoice[] }[] = [
  { unit: 1, title: 'Let’s Celebrate!', questions: [
    { section: 2, point: 2, task: 'festival-dialogue-detail', prompt: 'Read the original dialogue.\n\nAmy: Grandma, why do we make rice balls for the Lantern Festival?\nGrandma: We make them round to share with family.\nAmy: So the shape reminds us of being together?\nGrandma: That is one meaning many families enjoy.', options: ['Amy asks about the meaning of a festival food.', 'Grandma says every family must follow the same custom.', 'Amy asks how to cook rice for dinner.', 'Grandma says the festival has no family meaning.'], answer: 0, explanation: 'Amy asks why the family makes rice balls, and Grandma connects their round shape with being together. The dialogue gives one family’s meaning, not a rule for every family.' },
    { section: 3, point: 2, task: 'festival-reading-main-idea', prompt: 'Read the original paragraph.\n\nAt the school festival, students set up a small “family traditions” table. Some brought photos, while others wrote a few lines about a meal or song they remembered. Visitors could ask questions, and students were reminded that families celebrate in different ways.', options: ['The table lets students share different family festival memories.', 'Every student celebrates festivals in exactly the same way.', 'The school asked families to bring expensive gifts.', 'Visitors were not allowed to ask the students questions.'], answer: 0, explanation: 'The examples are family photos, meals, and songs, and the paragraph emphasizes that families celebrate differently.' },
    { section: 4, point: 1, task: 'simple-present-in-context', prompt: 'Choose the correct form to complete the original context.\n\nEvery year, our family ______ a story about the Spring Festival before dinner.', options: ['share', 'shares', 'shared tomorrow', 'is share'], answer: 1, explanation: '“Every year” signals a regular action. “Our family” is treated as a singular subject here, so the simple present form is “shares.”' },
    { section: 5, point: 2, task: 'festival-notice-detail', prompt: 'Read the original notice.\n\nFamily Story Afternoon\nSaturday, 1:30–3:00 p.m.\nRoom 204\nBring one short story, photo, or song connected with a celebration. Students may share in English or Chinese.', options: ['Students may bring a photo connected with a celebration.', 'The event is on Sunday morning.', 'Every student must sing alone in English.', 'The event will be held in the school hall.'], answer: 0, explanation: 'The notice lists a story, photo, or song as possible things to bring. It gives Saturday afternoon and Room 204 as the time and place.' },
    { section: 6, point: 1, task: 'festival-word-in-context', prompt: 'Read the original sentence.\n\nBefore the guests arrived, the cousins gathered in the kitchen to prepare the holiday meal.\n\nWhat does “gathered” mean here?', options: ['Came together in one place.', 'Left the house one by one.', 'Finished eating quickly.', 'Bought food from a shop.'], answer: 0, explanation: 'The cousins are together in the kitchen before the guests arrive, so “gathered” means came together in one place.' },
    { section: 7, point: 2, task: 'festival-paragraph-order', prompt: 'Choose the order that makes the original paragraph about a family celebration easiest to follow.\n\n① After dinner, everyone shared a story from an earlier festival.\n② First, the family prepared food and set the table.\n③ When the guests arrived, they sat down together.', options: ['②③①', '①②③', '③①②', '②①③'], answer: 0, explanation: 'The paragraph moves in time: preparation happens first, guests arrive next, and stories are shared after dinner.' },
  ] },
  { unit: 2, title: 'A Look into the Past', questions: [
    { section: 2, point: 2, task: 'history-dialogue-evidence', prompt: 'Read the original dialogue.\n\nLeo: This old photograph shows the river before the new bridge was built.\nNina: How can you tell?\nLeo: The caption gives the year, and the riverbank in the background matches the town map from that time.', options: ['Leo uses details in the caption and background as evidence.', 'Nina says the photograph was taken yesterday.', 'The students decide that maps are never useful.', 'Leo guesses the year from the color of the photograph alone.'], answer: 0, explanation: 'Leo points to two sources of evidence: the caption and a matching feature on a map. He does not rely only on a guess.' },
    { section: 3, point: 2, task: 'history-reading-evidence-limit', prompt: 'Read the original paragraph.\n\nA class found an old map of their town. It showed a road leading to the river, but it did not explain who used the road or why. The students compared the map with a diary from the same period before writing their report.', options: ['One source can raise questions, so the students compare it with another source.', 'The map answers every question about people’s lives.', 'The students ignore the diary because it is not a map.', 'The road must have been built for the same purpose as a modern road.'], answer: 0, explanation: 'The map shows the road but leaves details unknown. The class checks a diary as another source before drawing conclusions.' },
    { section: 4, point: 1, task: 'past-passive-in-context', prompt: 'Choose the correct form to complete the original context.\n\nThe town museum ______ in an old railway station in 1985.', options: ['opens', 'opened', 'was opened', 'has opening'], answer: 2, explanation: 'The museum received the action, and “in 1985” gives a finished past time. The simple past passive “was opened” is correct.' },
    { section: 5, point: 2, task: 'museum-notice-detail', prompt: 'Read the original museum notice.\n\nLocal History Room\nOpen Tuesday–Saturday, 10 a.m.–4 p.m.\nFree for students\nPlease do not touch the objects. Ask the guide before taking photographs.', options: ['Students can visit the room free of charge.', 'The room is open every Sunday evening.', 'Visitors may touch objects after taking a photo.', 'Students must book a ticket one month ahead.'], answer: 0, explanation: 'The notice says entry is free for students. It also gives the opening days and asks visitors not to touch objects.' },
    { section: 6, point: 1, task: 'history-word-in-context', prompt: 'Read the original sentence.\n\nThe archivist placed the letters in special folders to preserve them, keeping the paper safe from light and damp.', options: ['Keep something in good condition for the future.', 'Copy something without reading it.', 'Sell something to a visitor.', 'Change a story to make it more exciting.'], answer: 0, explanation: 'The folders protect the letters from damage, so “preserve” means keep something in good condition.' },
    { section: 7, point: 2, task: 'history-process-order', prompt: 'Choose the order that makes the original report about a museum object easiest to follow.\n\n① The museum displayed it with a note about what is known and unknown.\n② Researchers recorded where the object was found.\n③ They compared it with other objects from the same period.', options: ['②③①', '①②③', '③①②', '②①③'], answer: 0, explanation: 'Researchers first record the find, then compare evidence, and finally display the object with an explanation.' },
  ] },
  { unit: 3, title: 'A Taste of Art', questions: [
    { section: 2, point: 2, task: 'art-dialogue-evidence', prompt: 'Read the original dialogue.\n\nBen: I like the second painting better. The blue lines make the river look quiet.\nMay: I prefer the first one because its bright colors feel lively.\nBen: We see the same place differently.', options: ['They support different opinions with details about color and lines.', 'They agree that one painting has no colors.', 'May says Ben is not allowed to have an opinion.', 'Ben chooses a painting because it is more expensive.'], answer: 0, explanation: 'Ben refers to the blue lines and May to bright colors. Their responses differ, and both connect an opinion with a visible feature.' },
    { section: 3, point: 2, task: 'art-reading-main-idea', prompt: 'Read the original paragraph.\n\nA student drew the school garden in the morning and again after rain. The flowers stayed in the same place, but the light and colors changed. In the second picture, dark clouds made the yellow flowers stand out.', options: ['The student shows how light and weather can change the feeling of a scene.', 'The student proves that flowers move after every rain.', 'The two pictures were made by different artists.', 'The paragraph explains how to grow yellow flowers.'], answer: 0, explanation: 'The paragraph compares the same garden at two times and explains how changed light and weather affect the picture.' },
    { section: 4, point: 1, task: 'relative-clause-in-context', prompt: 'Choose the correct word to complete the original context.\n\nThe student ______ painted the city scene will talk about her work today.', options: ['who', 'where', 'when', 'whose'], answer: 0, explanation: 'The missing relative pronoun refers to “the student,” a person who performs the action “painted.” “Who” is correct.' },
    { section: 5, point: 2, task: 'gallery-notice-detail', prompt: 'Read the original gallery notice.\n\nStudent Art Show\nThursday, 3:30–5:00 p.m.\nLibrary Gallery\nVisitors may write one comment card. Please do not use flash photography.', options: ['Visitors may leave a comment about the show.', 'The show is in the gym on Friday morning.', 'Flash photography is required.', 'Only the student artists may enter the gallery.'], answer: 0, explanation: 'The notice invites visitors to write a comment card and asks them not to use flash photography.' },
    { section: 6, point: 1, task: 'art-word-in-context', prompt: 'Read the original sentence.\n\nThe painter used a pale blue shade for the sky and a much darker blue for the water.', options: ['A particular form or tone of a color.', 'A brush used to paint a wall.', 'A frame placed around a picture.', 'A person who visits an art show.'], answer: 0, explanation: 'The sentence compares two versions of blue, one pale and one dark. A “shade” is a particular tone of a color.' },
    { section: 7, point: 2, task: 'art-process-order', prompt: 'Choose the order that makes the original description of an art project easiest to follow.\n\n① Finally, she added color and displayed the finished work.\n② First, Mei sketched the shapes in pencil.\n③ Next, she chose which details to make larger.', options: ['②③①', '①②③', '③①②', '②①③'], answer: 0, explanation: 'The steps are marked by “First,” “Next,” and “Finally,” so the correct sequence is ②③①.' },
  ] },
  { unit: 4, title: 'Reduce, Reuse, Recycle', questions: [
    { section: 2, point: 2, task: 'recycling-dialogue-detail', prompt: 'Read the original dialogue.\n\nKai: Can this paper cup go in the paper-recycling box?\nRosa: Not if it is wet or has food on it. Put a clean sheet of paper in the box, though.\nKai: I’ll check it before I sort it.', options: ['The paper box is for clean paper, not a wet cup.', 'Rosa says every kind of rubbish belongs in the paper box.', 'Kai decides to throw all paper on the ground.', 'The students are asked to stop using the bins.'], answer: 0, explanation: 'Rosa distinguishes a wet cup from a clean sheet of paper. Kai agrees to check the item before sorting it.' },
    { section: 3, point: 2, task: 'recycling-reading-result', prompt: 'Read the original paragraph.\n\nFor one month, a class put a box beside the printer for paper with one clean side. Students used those sheets for rough work. At the end of the month, the class had used fewer new sheets, although the project did not remove all paper waste.', options: ['Reusing paper reduced the number of new sheets the class needed.', 'The class stopped using paper completely.', 'Students put wet food into the printer box.', 'The project made every student print more pages.'], answer: 0, explanation: 'Students reused paper for rough work and needed fewer new sheets. The paragraph clearly says some paper waste remained.' },
    { section: 4, point: 1, task: 'first-conditional-in-context', prompt: 'Choose the correct form to complete the original context.\n\nIf we ______ a reusable bottle, we can avoid taking a new plastic cup each time.', options: ['bring', 'brought yesterday', 'will bring', 'are bring'], answer: 0, explanation: 'A real possible condition uses the simple present in the if-clause: “If we bring …, we can avoid …”.' },
    { section: 5, point: 2, task: 'recycling-notice-detail', prompt: 'Read the original notice.\n\nPaper Collection Week\nPlace clean, dry paper in the blue box beside the library.\nDo not include tissues or paper with food on it.\nThe collection ends Friday at 4 p.m.', options: ['Clean, dry paper should go in the blue box.', 'Tissues are listed as the best items to recycle.', 'The collection ends next Monday morning.', 'The blue box is beside the cafeteria.'], answer: 0, explanation: 'The notice specifies clean, dry paper and places the box beside the library.' },
    { section: 6, point: 1, task: 'environment-word-in-context', prompt: 'Read the original sentence.\n\nThe club asked students to reduce waste by using both sides of a sheet before recycling it.', options: ['Make the amount smaller.', 'Separate into equal groups.', 'Make something dirty.', 'Buy more than is needed.'], answer: 0, explanation: 'Using both sides means fewer sheets are thrown away, so “reduce” means make the amount smaller.' },
    { section: 7, point: 2, task: 'recycling-process-order', prompt: 'Choose the order that makes the original recycling instructions easiest to follow.\n\n① Put the clean, dry paper in the marked box.\n② Check that the paper has no food or liquid on it.\n③ Read the label on the collection box.', options: ['③②①', '①②③', '②①③', '③①②'], answer: 0, explanation: 'First read what the box accepts, then check the paper, and finally put suitable paper in the box.' },
  ] },
  { unit: 5, title: 'Open to New Beginnings', questions: [
    { section: 2, point: 2, task: 'new-beginning-dialogue-purpose', prompt: 'Read the original dialogue.\n\nEvan: I’m new here and don’t know where to find the science room.\nJia: I can show you after lunch. The library is next to it.\nEvan: Thanks. I also want to find a club where I can practise drawing.', options: ['Evan asks for help finding places and a chance to join an activity.', 'Jia tells Evan to leave the school.', 'Evan says he has already visited every room.', 'Jia asks Evan to teach a science lesson.'], answer: 0, explanation: 'Evan needs directions and wants to find a drawing club. Jia offers practical help.' },
    { section: 3, point: 2, task: 'new-beginning-reading-main-idea', prompt: 'Read the original paragraph.\n\nAt the start of the term, Omar wrote down two goals: speak more English in class and learn the names of his new classmates. He practised one short answer each day and greeted someone new at lunch. By the end of the month, both goals felt easier.', options: ['Small regular steps helped Omar work toward two personal goals.', 'Omar decided that goals are never useful.', 'Omar learned English without practising.', 'The paragraph is mainly about choosing lunch food.'], answer: 0, explanation: 'The paragraph names two goals and gives a small repeated action for each, then describes progress.' },
    { section: 4, point: 1, task: 'present-perfect-in-context', prompt: 'Choose the correct form to complete the original context.\n\nSince joining the school, Priya ______ two new friends and found the art room.', options: ['makes', 'made tomorrow', 'has made', 'is make'], answer: 2, explanation: '“Since joining the school” describes a period continuing up to now, so the present perfect “has made” is appropriate.' },
    { section: 5, point: 2, task: 'orientation-notice-detail', prompt: 'Read the original orientation notice.\n\nNew Student Tour\nMeet at the main entrance on Monday at 9:15 a.m.\nThe tour will visit the library, science rooms, and student office.\nBring your timetable.\nQuestions? Ask Ms. Chen in Room 12.', options: ['Students should bring their timetables.', 'The tour starts at the student office on Friday.', 'The tour includes a visit to the school shop.', 'Students must ask Ms. Chen before Monday by email.'], answer: 0, explanation: 'The notice asks students to bring their timetables and lists the meeting place and stops.' },
    { section: 6, point: 1, task: 'new-beginning-word-in-context', prompt: 'Read the original sentence.\n\nAfter practising her introduction with a friend, Mei felt more confident about speaking to the new class.', options: ['Sure of herself and less worried.', 'Unable to remember her name.', 'Angry that the class was changing.', 'Certain that no one would listen.'], answer: 0, explanation: 'Practising helps Mei feel ready to speak, so “confident” means sure of herself and less worried.' },
    { section: 7, point: 2, task: 'goal-paragraph-order', prompt: 'Choose the order that makes the original paragraph about a new goal easiest to follow.\n\n① Each Friday, he checks what worked and plans one next step.\n② At the beginning of the term, Daniel chose to read one English story each week.\n③ He keeps a short list of new words while he reads.', options: ['②③①', '①②③', '③①②', '②①③'], answer: 0, explanation: 'The paragraph introduces Daniel’s goal, explains how he follows it, and ends with a regular review step.' },
  ] },
]

// Unit q3 used the same short passage and three repeated detail questions in every section.
// Give each published section its own original, evidence-based reading item.
const g9UnitQ3Templates: { unit: number; title: string; questions: UnitChoice[] }[] = [
  { unit: 1, title: 'Let’s Celebrate!', questions: [
    { section: 1, point: 2, task: 'family-call-detail', prompt: 'Read the original message.\n\nMina’s grandparents live far away. Before the Spring Festival dinner, her family calls them and lets each person share one piece of news. Mina says the call makes the celebration feel complete.\n\nWhy does Mina’s family call before dinner?', options: ['To share the celebration with relatives who live far away.', 'To ask the grandparents to cook the dinner.', 'To cancel the family celebration.', 'To tell them that the family has moved.'], answer: 0, explanation: 'The message says each person shares news with the grandparents, who live far away; the call helps them take part in the celebration.' },
    { section: 2, point: 2, task: 'family-recipe-purpose', prompt: 'Read the original dialogue.\n\nA: Why are you writing down your aunt’s dumpling recipe?\nB: She learned it from my great-grandmother. I want my little brother to be able to make it, too.\nA: Then add a photo of the steps.', options: ['The recipe is being recorded so a younger family member can learn it.', 'The family plans to stop making dumplings.', 'The aunt wants to sell the recipe to a restaurant.', 'The photo is meant to replace the recipe.'], answer: 0, explanation: 'B wants the younger brother to learn a recipe passed through the family; the photo would help explain the steps.' },
    { section: 3, point: 2, task: 'festival-display-purpose', prompt: 'Read the original paragraph.\n\nFor Culture Day, each student brought an object connected with a celebration. Omar brought a paper decoration and explained when his family hangs it. His classmates asked questions and added their own examples.\n\nWhat was the main purpose of the activity?', options: ['To let students share and learn about celebration customs.', 'To choose the most expensive decoration.', 'To teach students how to sell paper objects.', 'To decide that all families celebrate in one way.'], answer: 0, explanation: 'Students brought objects, explained their family customs, and exchanged examples, so the activity was for sharing and learning.' },
    { section: 4, point: 2, task: 'festival-story-inference', prompt: 'Read the original note.\n\nGrandpa wrote that, when he was young, his family saved one orange for the New Year table. This year, he gave the orange to his granddaughter and asked her to add a family story to the display.\n\nWhat does Grandpa most likely hope the story will do?', options: ['Help the younger generation understand a family memory.', 'Prove that oranges can only be eaten in winter.', 'Replace every other New Year custom.', 'Show that the display is a cooking contest.'], answer: 0, explanation: 'Grandpa connects a past family practice with the present display, suggesting he wants his granddaughter to know the memory behind it.' },
    { section: 5, point: 2, task: 'festival-notice-time', prompt: 'Read the original notice.\n\nLantern Walk\nMeet at the school gate at 6:20 p.m. on Thursday. The walk starts at 6:30 and ends at the riverside garden. Bring a warm coat. The event will move to the gym if it rains.\n\nWhere should students go if it rains?', options: ['The gym.', 'The riverside garden.', 'The school library.', 'The main office.'], answer: 0, explanation: 'The notice says the event moves to the gym in rainy weather.' },
    { section: 6, point: 2, task: 'reunion-word-in-context', prompt: 'Read the original sentence.\n\nAlthough the cousins live in different cities, the holiday meal is a reunion: they meet again, share stories, and spend time together.\n\nWhat does “reunion” mean here?', options: ['A meeting of people who have been apart.', 'A plan to move to another city.', 'A lesson about cooking.', 'A competition between cousins.'], answer: 0, explanation: 'The cousins have been living apart and meet again for the meal, so “reunion” means a meeting after being separated.' },
    { section: 7, point: 2, task: 'celebration-custom-conclusion', prompt: 'Read the original paragraph.\n\nIn one family, everyone writes a wish on a small card at New Year. In another, people call relatives before midnight. Their class display includes both customs and explains that families may welcome the same holiday in different ways.\n\nWhich conclusion is supported?', options: ['A holiday can include different customs in different families.', 'Every family must follow the same New Year custom.', 'The two families do not celebrate any holiday.', 'Only written wishes can be part of a celebration.'], answer: 0, explanation: 'The paragraph gives two different customs for the same holiday and explicitly says families may celebrate in different ways.' },
    { section: 8, point: 2, task: 'festival-project-audience', prompt: 'Read the original project note.\n\nThe class is making a festival guide for new students. Each page will name a celebration, give the time of year, and explain one custom in simple English. The group plans to check unfamiliar details with a family member.\n\nWhy will the group use simple English?', options: ['The guide is for new students who may be unfamiliar with the celebration.', 'The students are not allowed to write complete sentences.', 'The guide is meant only for the family member.', 'The group wants to leave out information about customs.'], answer: 0, explanation: 'The project note names new students as the audience, so clear, simple language will help them understand the guide.' },
    { section: 9, point: 2, task: 'festival-program-detail', prompt: 'Read the original program.\n\n2:00 — Welcome song\n2:15 — Family celebration stories\n2:45 — Paper craft table\n3:20 — Closing and clean-up\n\nWhat begins at 2:45?', options: ['The paper craft activity.', 'The welcome song.', 'The family stories.', 'Clean-up.'], answer: 0, explanation: 'The program lists the paper craft table at 2:45.' },
    { section: 10, point: 2, task: 'festival-object-inference', prompt: 'Read the original paragraph.\n\nMei’s family keeps an old festival card in a box. It has no price written on it, but each year Mei’s mother takes it out and tells the children who made it and why the family saved it.\n\nWhy is the card valuable to the family?', options: ['It carries a family memory, not just a market price.', 'It is the newest card in the shop.', 'It lists the dates of every school holiday.', 'It can be used as a train ticket.'], answer: 0, explanation: 'The family keeps the card and tells its story each year. Its importance comes from the memory attached to it.' },
  ] },
  { unit: 2, title: 'A Look into the Past', questions: [
    { section: 1, point: 2, task: 'museum-artifact-evidence', prompt: 'Read the original museum note.\n\nA clay bowl was found beside an old village wall. Its shape suggests it may have held grain, but the note says researchers cannot know who used it.\n\nWhat does the bowl provide evidence about?', options: ['An object people may have used in daily life.', 'The name of every person in the village.', 'The exact words spoken near the wall.', 'The date when the museum opened.'], answer: 0, explanation: 'The shape suggests a possible use in daily life, but the note warns that the user is unknown.' },
    { section: 2, point: 2, task: 'old-photo-caption', prompt: 'Read the original caption.\n\n“Market Street, 1932.” The photograph shows a horse cart beside the post office. A later town map marks the same post office at the corner of Market and Pine Streets.\n\nWhich detail helps identify where the photograph was taken?', options: ['The post office matches a location on a later map.', 'The horse cart was painted red.', 'The photograph has a narrow border.', 'The street is busy in the picture.'], answer: 0, explanation: 'The matching post-office location on the map is specific evidence that helps locate the photograph.' },
    { section: 3, point: 2, task: 'diary-source-limit', prompt: 'Read the original paragraph.\n\nA student found a diary entry that says the river market was crowded on Tuesday. The entry describes one day, so the student checks other records before writing that the market was always crowded.\n\nWhy does the student check more records?', options: ['One entry about one day cannot prove what happened every day.', 'A diary can never contain useful information.', 'The student wants to remove Tuesday from the calendar.', 'The market was not near a river.'], answer: 0, explanation: 'The diary describes one day only. More evidence is needed to support a claim about what happened regularly.' },
    { section: 4, point: 2, task: 'bridge-record-comparison', prompt: 'Read the original report.\n\nA town record says the stone bridge was repaired in 1910. An old photograph taken three years later shows a wooden bridge at the same bend in the river. The class plans to ask the museum whether the photograph has the right date.\n\nWhat question should the class check first?', options: ['Whether the photograph’s date and location are correct.', 'Whether every bridge was made of stone.', 'Whether the river has the same name today.', 'Whether the photographer liked the town.'], answer: 0, explanation: 'The record and photograph seem to conflict, so verifying the photograph’s date and location is the first useful step.' },
    { section: 5, point: 2, task: 'archive-notice-detail', prompt: 'Read the original notice.\n\nTown Archive Visit\nWednesday, 2:00–3:30 p.m.\nBring a pencil and student card. Bags must stay in the lockers. Ask the archivist before opening a document box.\n\nWhat should students bring?', options: ['A pencil and student card.', 'A camera and a large bag.', 'A document box from home.', 'A visitor pass for Friday.'], answer: 0, explanation: 'The notice directly asks students to bring a pencil and student card.' },
    { section: 6, point: 2, task: 'inscription-word-in-context', prompt: 'Read the original sentence.\n\nThe team found an inscription carved above the doorway. It included a date and the name of the person who paid for the building.\n\nWhat is an “inscription” here?', options: ['Words cut or written on a surface.', 'A tool for measuring a doorway.', 'A map of the surrounding streets.', 'A story told aloud at a museum.'], answer: 0, explanation: 'The words and date are carved above the doorway, so an “inscription” is writing on a surface.' },
    { section: 7, point: 2, task: 'history-source-support', prompt: 'Read the original paragraph.\n\nA family letter says that the old station was busy on market days. A timetable from the same year shows trains arriving every hour. Together, the sources help explain why many people gathered near the station.\n\nWhat makes the explanation stronger?', options: ['Two different sources support the idea that many people came there.', 'The letter and timetable were written by the same person.', 'The paragraph gives no dates or details.', 'The station is described as empty.'], answer: 0, explanation: 'The letter and timetable provide different kinds of evidence that support the explanation.' },
    { section: 8, point: 2, task: 'museum-label-purpose', prompt: 'Read the original exhibit label.\n\nThis wooden ruler was used in the town school around 100 years ago. The ruler shows how pupils measured lines before digital tools were common. The exact owner is not known.\n\nWhy does the label mention that the owner is unknown?', options: ['To separate what the evidence shows from what researchers cannot confirm.', 'To suggest that the ruler never belonged to anyone.', 'To prove that every pupil used this ruler.', 'To ask visitors to take the ruler home.'], answer: 0, explanation: 'The label gives a likely use but does not claim an identity without evidence.' },
    { section: 9, point: 2, task: 'past-source-difference', prompt: 'Read the original paragraph.\n\nTwo old maps show the same square with different names. One was drawn before the railway arrived; the other was printed ten years later. A student checks the dates before deciding whether the names changed.\n\nWhy are the dates important?', options: ['The maps may record the place at different times.', 'The dates show how much the maps cost.', 'A map cannot show a place name.', 'The later map must be incorrect.'], answer: 0, explanation: 'The maps come from different years, so the name may have changed over time; the dates help explain the difference.' },
    { section: 10, point: 2, task: 'historical-event-order', prompt: 'Read the original paragraph.\n\nFirst, workers built a small station outside town. Later, shops opened nearby. Years afterward, the town added a road connecting the station with the market.\n\nWhich event happened second?', options: ['Shops opened near the station.', 'Workers built the station.', 'The town added a road to the market.', 'The market closed.'], answer: 0, explanation: 'The paragraph orders the events: station first, shops later, and the connecting road years afterward.' },
  ] },
  { unit: 3, title: 'A Taste of Art', questions: [
    { section: 1, point: 2, task: 'painting-feature-response', prompt: 'Read the original dialogue.\n\nA: The long blue lines make the river look quiet to me.\nB: I notice the bright yellow window first. It makes the room feel warm.\nA: We looked at the same painting but noticed different details.', options: ['Each viewer supports a personal response with a visible feature.', 'The viewers agree that the painting has no color.', 'The dialogue is mainly about the price of paint.', 'One viewer says that personal responses are not allowed.'], answer: 0, explanation: 'One speaker notices blue lines and the other a yellow window; each links an opinion with a feature in the painting.' },
    { section: 2, point: 2, task: 'art-material-detail', prompt: 'Read the original note.\n\nThe artist made the first sketch in pencil. She then used watercolors for the background and left a few white spaces on the paper to show light on the lake.\n\nHow did the artist show light on the lake?', options: ['By leaving some paper white.', 'By covering the whole page with dark paint.', 'By drawing a frame around the lake.', 'By adding words to the background.'], answer: 0, explanation: 'The note says the artist left white spaces on the paper to show light.' },
    { section: 3, point: 2, task: 'gallery-feedback-purpose', prompt: 'Read the original paragraph.\n\nAt the student gallery, visitors placed a small note beside their favorite artwork. Some described the colors; others wrote how the picture made them feel. The artists read the notes after the show.\n\nWhat was the purpose of the notes?', options: ['To let visitors share responses with the artists.', 'To vote on which artist could keep painting.', 'To record the gallery’s opening hours.', 'To tell visitors not to look at the pictures.'], answer: 0, explanation: 'The notes record what visitors noticed or felt, and the artists read them after the show.' },
    { section: 4, point: 2, task: 'artwork-caption-identification', prompt: 'Read the original caption.\n\n“Rainy Window,” painted by Chen Rui in 2024. The artist used grey-blue colors and thin lines to show drops on the glass.\n\nWhich statement is supported by the caption?', options: ['The picture was painted by Chen Rui in 2024.', 'The picture shows a sunny beach in summer.', 'The artist used only thick red lines.', 'The caption gives the painting’s sale price.'], answer: 0, explanation: 'The caption gives the title, artist, year, colors, and lines; it does not mention a beach or price.' },
    { section: 5, point: 2, task: 'sculpture-process-detail', prompt: 'Read the original paragraph.\n\nFor her clay model, Nia shaped the body first and let it dry. Then she added small patterns with a wooden tool. She waited until the clay was firm before painting it.\n\nWhat did Nia do before painting the model?', options: ['She waited for the clay to become firm.', 'She painted the wet clay before shaping it.', 'She removed every pattern from the model.', 'She placed the model in water.'], answer: 0, explanation: 'The paragraph says Nia waited until the clay was firm before painting.' },
    { section: 6, point: 2, task: 'art-pattern-word-in-context', prompt: 'Read the original sentence.\n\nThe artist repeated small circles across the cloth; this pattern made the plain surface look lively.\n\nWhat does “pattern” mean here?', options: ['A repeated design.', 'A kind of paintbrush.', 'A person who buys cloth.', 'A room for displaying art.'], answer: 0, explanation: 'The circles repeat across the cloth, so “pattern” means a repeated design.' },
    { section: 7, point: 2, task: 'mosaic-detail', prompt: 'Read the original paragraph.\n\nThe class made a mosaic from small pieces of colored paper. From far away the pieces formed a tree, but up close each square had a different shade.\n\nWhat can a viewer notice by looking from two distances?', options: ['The whole image and the separate colored pieces.', 'Only the paper’s price.', 'That every piece has the same shade.', 'That the class used no paper.'], answer: 0, explanation: 'From far away the pieces form a tree; up close viewers can see the individual shades.' },
    { section: 8, point: 2, task: 'art-label-evidence', prompt: 'Read the original label.\n\n“Evening Street,” by Luo An: the lamps are small, but their reflections stretch across the wet road. To me, the long reflections make the street feel peaceful.\n\nWhich part is the writer’s personal response?', options: ['“The street feel[s] peaceful.”', 'The title “Evening Street.”', 'The artist’s name.', 'The lamps are small.'], answer: 0, explanation: 'The title, artist, and lamp detail are factual description; saying the street feels peaceful is the writer’s response.' },
    { section: 9, point: 2, task: 'artist-choice-inference', prompt: 'Read the original paragraph.\n\nA portrait shows a girl looking toward an open door. The artist placed most of the light near the doorway, while the rest of the room is darker.\n\nWhat might the artist be drawing attention to?', options: ['The open doorway and the girl’s direction of gaze.', 'The price of the frame.', 'The number of people in the gallery.', 'The color of the floor outside the room.'], answer: 0, explanation: 'The light near the open door and the girl’s gaze both direct attention toward that area.' },
    { section: 10, point: 2, task: 'gallery-review-evidence', prompt: 'Read the original review.\n\nI liked the print because it shows the same bridge in two seasons. In the winter half, bare branches make the river seem quiet; in the spring half, green leaves make it feel lively.\n\nWhich detail supports the reviewer’s contrast?', options: ['Bare branches in winter and green leaves in spring.', 'The size of the gallery room.', 'The name of the print shop.', 'The number of visitors on opening day.'], answer: 0, explanation: 'The review uses the two different sets of branches and leaves to explain its contrast between quiet and lively.' },
  ] },
  { unit: 4, title: 'Reduce, Reuse, Recycle', questions: [
    { section: 1, point: 2, task: 'paper-bin-rule', prompt: 'Read the original notice.\n\nPut clean, dry paper in the blue box beside the library. Do not put tissues or paper with food on it in the box. The club will empty it on Friday.\n\nWhich item belongs in the blue box?', options: ['A clean, dry worksheet.', 'A wet tissue.', 'A paper plate with food on it.', 'A plastic bottle.'], answer: 0, explanation: 'The notice accepts clean, dry paper and excludes tissues and paper with food.' },
    { section: 2, point: 2, task: 'reusable-bottle-reason', prompt: 'Read the original dialogue.\n\nA: I brought my own bottle today.\nB: Good idea. You can refill it at the water station instead of taking a new cup each time.\nA: That should mean fewer disposable cups.\n\nWhy does the first student bring a bottle?', options: ['To refill it and avoid using a new disposable cup each time.', 'To collect paper for the library.', 'To keep the water station closed.', 'To use it only as a flower pot.'], answer: 0, explanation: 'The dialogue states that refilling the bottle can replace taking a new disposable cup.' },
    { section: 3, point: 2, task: 'waste-audit-result', prompt: 'Read the original report.\n\nA class checked the lunch bins for five days. Most of the clean paper was in the general-waste bin. The class placed a paper box nearby and plans to check again next week.\n\nWhat will the second check help the class find out?', options: ['Whether more paper is being sorted into the paper box.', 'Whether the lunch period has moved to the morning.', 'Whether students have stopped eating lunch.', 'Whether the bins are made of paper.'], answer: 0, explanation: 'The class changed where the paper box is placed; checking again can show whether sorting improves.' },
    { section: 4, point: 2, task: 'compost-project-detail', prompt: 'Read the original paragraph.\n\nThe garden club collects fruit peels from the school kitchen. It mixes them with dry leaves in a covered compost box. The club will use the finished compost in the garden beds.\n\nWhat will the club do with the finished compost?', options: ['Use it in the garden beds.', 'Put it back into the lunch trays.', 'Use it to make paper boxes.', 'Send it to the art gallery.'], answer: 0, explanation: 'The paragraph says the finished compost will be used in the garden beds.' },
    { section: 5, point: 2, task: 'sorting-instruction-detail', prompt: 'Read the original instructions.\n\n1. Empty the drink from the bottle. 2. Rinse it. 3. Put it in the marked container beside the gym.\n\nWhere should the bottle go after it is rinsed?', options: ['In the marked container beside the gym.', 'In the lunch tray.', 'In the paper box beside the library.', 'Back on the shelf at home.'], answer: 0, explanation: 'The last step says to put the rinsed bottle in the marked container beside the gym.' },
    { section: 6, point: 2, task: 'discard-word-in-context', prompt: 'Read the original sentence.\n\nInstead of discarding the chipped mug, Sam uses it to hold pencils on his desk.\n\nWhat does “discarding” mean?', options: ['Throwing something away.', 'Painting something carefully.', 'Borrowing something for a day.', 'Giving something a new name.'], answer: 0, explanation: 'Sam keeps the mug and gives it another use instead of throwing it away; “discard” means throw away.' },
    { section: 7, point: 2, task: 'repair-before-replace', prompt: 'Read the original paragraph.\n\nWhen a classroom chair became loose, the students told the teacher. The school repair worker tightened its screws, and the chair was used again. The class added “check before replacing” to its reuse poster.\n\nWhat idea does the example support?', options: ['Repairing an item can keep it useful for longer.', 'Every loose chair should be thrown away.', 'Students should repair furniture without permission.', 'A poster can replace classroom furniture.'], answer: 0, explanation: 'The chair was repaired and used again, illustrating that repair can extend an item’s use.' },
    { section: 8, point: 2, task: 'campaign-data-interpretation', prompt: 'Read the original report.\n\nBefore the campaign, the school used 40 disposable cups at a club meeting. At the next meeting, students brought reusable cups and used 14 disposable cups. The report says the number fell, but it does not say that all cups were eliminated.\n\nWhich statement is supported?', options: ['The second meeting used fewer disposable cups, but not zero.', 'The first meeting used no disposable cups.', 'The campaign stopped every kind of waste.', 'The second meeting used more than 40 disposable cups.'], answer: 0, explanation: 'The numbers show a decrease from 40 to 14, and the report explicitly says some disposable cups were still used.' },
    { section: 9, point: 2, task: 'water-saving-action', prompt: 'Read the original notice.\n\nThe science room tap was left running after an experiment twice this week. From now on, the last group must check the tap and report a leak to the teacher.\n\nWhat action does the notice ask students to take?', options: ['Check that the tap is off and report leaks.', 'Leave the tap running to clean the room.', 'Use water to wash paper for recycling.', 'Stop doing science experiments.'], answer: 0, explanation: 'The notice asks the last group to check the tap and tell the teacher if it leaks.' },
    { section: 10, point: 2, task: 'reuse-recycle-difference', prompt: 'Read the original paragraph.\n\nA glass jar can be washed and used again to store buttons. If the family no longer needs it, the clean jar can be placed in the glass-recycling box.\n\nWhich action happens before recycling the jar?', options: ['Using the washed jar again to store buttons.', 'Breaking the jar on purpose.', 'Putting food waste into the glass box.', 'Buying a new jar each week.'], answer: 0, explanation: 'The paragraph gives reuse as one option first; recycling is a later option if the family no longer needs the jar.' },
  ] },
  { unit: 5, title: 'Open to New Beginnings', questions: [
    { section: 1, point: 2, task: 'new-student-request', prompt: 'Read the original message.\n\nHi, I’m Alex. I joined Class 9 this week. I can find the library now, but I’m not sure which room the music club uses. Could someone show me after lunch?\n\nWhat help does Alex ask for?', options: ['Directions to the music club room.', 'A new library card for every student.', 'Permission to leave school early.', 'A music lesson before breakfast.'], answer: 0, explanation: 'Alex already knows where the library is and asks where the music club meets.' },
    { section: 2, point: 2, task: 'goal-setting-routine', prompt: 'Read the original paragraph.\n\nAt the start of term, Hana wanted to speak more in English class. She wrote one question in her notebook each evening and tried to ask it the next day. After several weeks, she felt less nervous.\n\nWhat helped Hana work toward her goal?', options: ['Preparing a question regularly and trying to use it.', 'Waiting until the last day of term.', 'Avoiding every class discussion.', 'Asking a friend to answer for her.'], answer: 0, explanation: 'Hana takes a small regular step by preparing a question and trying to ask it in class.' },
    { section: 3, point: 2, task: 'school-map-detail', prompt: 'Read the original directions.\n\nFrom the main entrance, walk past the office and turn left at the stairs. The science rooms are at the end of the hall, opposite the library.\n\nWhere are the science rooms?', options: ['At the end of the hall, opposite the library.', 'Beside the main entrance.', 'Inside the school office.', 'At the top of the stairs behind the gym.'], answer: 0, explanation: 'The directions place the science rooms at the end of the hall, opposite the library.' },
    { section: 4, point: 2, task: 'future-plan-reason', prompt: 'Read the original note.\n\nNoah wants to join the school art club, but he has not used the printmaking tools before. He plans to ask the club teacher which beginner session is suitable.\n\nWhy will Noah ask the teacher?', options: ['To find a session that fits his experience.', 'To cancel every club activity.', 'To borrow tools without learning how to use them.', 'To change the school timetable.'], answer: 0, explanation: 'Noah is new to the tools and wants advice about a suitable beginner session.' },
    { section: 5, point: 2, task: 'orientation-notice-time', prompt: 'Read the original notice.\n\nNew Student Tour\nMeet at the main entrance at 9:15 a.m. Monday. Bring your timetable. The tour visits the library and science rooms before lunch.\n\nWhat should a new student bring?', options: ['A timetable.', 'A packed dinner for the tour guide.', 'A paintbrush for the library.', 'A visitor pass for Friday.'], answer: 0, explanation: 'The notice explicitly asks new students to bring their timetables.' },
    { section: 6, point: 2, task: 'settle-in-phrase', prompt: 'Read the original sentence.\n\nThe first week felt busy, but after a few days Ella knew where to go and had someone to sit with at lunch. She began to settle in.\n\nWhat does “settle in” mean here?', options: ['Become comfortable in a new place or situation.', 'Move house to another city.', 'Finish a school term early.', 'Choose a seat for a visitor.'], answer: 0, explanation: 'Ella learns the routines and finds company, so “settle in” means become comfortable in the new situation.' },
    { section: 7, point: 2, task: 'club-invitation-response', prompt: 'Read the original dialogue.\n\nA: I like taking photos, but I don’t know anyone in the photography club.\nB: Come with me on Thursday. New members can try a short photo walk before they decide.\n\nWhat makes the invitation helpful?', options: ['It offers a low-pressure way to try the club before joining.', 'It says the student must join without asking questions.', 'It asks the student to buy a new camera first.', 'It promises that every photo will win a prize.'], answer: 0, explanation: 'The student can try a short activity before deciding, which makes joining less difficult.' },
    { section: 8, point: 2, task: 'first-week-plan', prompt: 'Read the original plan.\n\nFor the first week, Rosa will learn two classroom locations each day. She has marked the rooms on a map and asked a classmate to check it with her after school.\n\nWhat is Rosa’s plan designed to do?', options: ['Help her learn the school layout step by step.', 'Help her avoid meeting classmates.', 'Replace the school’s timetable.', 'Prepare her to lead every class.'], answer: 0, explanation: 'Rosa uses a map and learns a few locations each day, a gradual way to become familiar with the school.' },
    { section: 9, point: 2, task: 'progress-reflection-evidence', prompt: 'Read the original reflection.\n\nAt the beginning of the term, Jun was afraid to read aloud. He practised a short paragraph with a partner twice a week. Last Friday, he volunteered to read one sentence to the class.\n\nWhich detail best shows Jun has made progress?', options: ['He volunteered to read a sentence to the class.', 'He was afraid at the beginning of term.', 'He has a partner in class.', 'The paragraph was short.'], answer: 0, explanation: 'Volunteering to read aloud is a clear change from being afraid to do so at the beginning.' },
    { section: 10, point: 2, task: 'supportive-advice', prompt: 'Read the original message.\n\nA new classmate says, “I’m worried that I won’t remember everyone’s name.” Mia replies, “It’s okay to ask again. We can write names on our group cards today.”\n\nWhy is Mia’s reply supportive?', options: ['It offers a practical way to learn names and reassures the classmate.', 'It tells the classmate to stop speaking to everyone.', 'It says that names do not matter at school.', 'It asks the classmate to leave the group.'], answer: 0, explanation: 'Mia acknowledges the worry, says it is okay to ask again, and suggests using group cards.' },
  ] },
]

